const tmp = (prefix: string) => fs.mkdtempSync(path.join(os.tmpdir(), prefix));
let home: string;
let workspace: string;
let savedHome: string | undefined;

before(() => {
  savedHome = process.env.HOME;
  home = tmp("nexus-doctor-home-");
  workspace = tmp("nexus-doctor-ws-");
  process.env.HOME = home;
});
after(() => {
  process.env.HOME = savedHome;
  fs.rmSync(home, { recursive: true, force: true });
  fs.rmSync(workspace, { recursive: true, force: true });
});

const cfg = (o: Partial<HarnessConfig> = {}): HarnessConfig => ({ endpoint: "http://127.0.0.1:9/v1", model: "m", maxSteps: 30, temperature: 0, workspace, shell: "bash", ...o });
const find = (report: DoctorReport, id: string) => report.findings.find((f) => f.id === id);
const doctor = (o: Parameters<typeof runDoctor>[0]) => runDoctor({ home, timeoutMs: 1500, ...(o as object) });

describe("doctor findings name the actual failure", () => {
  test("sandbox.confinement states the effective containment when no sandbox is configured (CS-1)", async () => {
    const finding = find(await doctor({ config: cfg() }), "sandbox.confinement")!;
    assert.equal(finding.status, "skip");
    assert.match(finding.explanation, /Effective sandbox profile: unconfined/);
    assert.ok(finding.evidence.some((e) => /^bubblewrap \(bwrap\): (available|not available)$/.test(e)));
    assert.match(finding.action ?? "", /--sandbox bwrap/);
  });

  test("sandbox.confinement says where the worker runs under Docker and names the files-only worker (CS-10)", async () => {
    const evidence = find(await doctor({ config: cfg({ sandbox: "docker" }) }), "sandbox.confinement")!.evidence.join("\n");
    if (process.platform === "linux") {
      assert.match(evidence, /native worker \(harness-core\): runs inside this sandbox/);
      assert.match(evidence, /files-only worker: it refuses to run commands and has no network even with --sandbox-network/);
    } else {
      assert.match(evidence, /runs outside Docker on this host/);
      assert.doesNotMatch(evidence, /files-only worker/);
    }
  });

