  private readonly connections = new Set<Connection>();
  private controller?: Connection;
  private token = newToken();
  private socketPath?: string;
  private descriptorPath?: string;
  private socketIdentity?: { dev: number; ino: number };
  private seq = 0;

  constructor(private readonly options: SessionSocketOptions) {
    this.session = options.session;
    this.server = net.createServer((socket) => this.accept(socket));
    this.server.on("error", (error) => options.onError?.(error));
  }

  get connectionCount(): number {
    return this.connections.size;
  }

  async listen(): Promise<SocketInfo> {
    const dir = this.options.dir ?? socketRuntimeDir();
    await sweepStaleSockets(dir);
    const name = this.options.name ?? newSocketName();
    const socketPath = path.join(dir, `${name}.sock`);
    const descriptorPath = path.join(dir, `${name}.json`);
    await prepareSocketPath(socketPath);
    await new Promise<void>((resolve, reject) => {
      this.server.once("error", reject);
      this.server.listen({ path: socketPath }, () => { this.server.off("error", reject); resolve(); });
    });
    this.socketPath = socketPath;
    try {
      fs.chmodSync(socketPath, 0o600);
      const stat = fs.lstatSync(socketPath);
      if (!stat.isSocket() || (stat.mode & 0o777) !== 0o600) throw new Error(`socket ${socketPath} is not mode 0600`);
      this.socketIdentity = { dev: stat.dev, ino: stat.ino };
      this.descriptorPath = descriptorPath;
      writeDescriptor(descriptorPath, { format: "nexus-socket/1", socket: socketPath, token: this.token, pid: process.pid, started_at: new Date().toISOString() });
    } catch (error) {
      await this.close();
      throw error;
    }
    return { socket: socketPath, descriptor: descriptorPath };
  }

  /** Sends one already-formatted protocol line to every attached client. */
  broadcast(line: string): void {
      try { fs.unlinkSync(socketPath.replace(/\.sock$/, ".json")); } catch { /* no descriptor */ }
      swept++;
    } catch { /* live, foreign or unreadable: left alone */ }
  }
  return swept;
}

export function writeDescriptor(file: string, descriptor: SocketDescriptor): void {
  writePrivateFile(file, `${JSON.stringify(descriptor)}\n`, { mode: 0o600 });
}

/** Reads a descriptor the way a client must: a regular file owned by this user, mode 0600, at most 4 KiB. */
export function readDescriptor(file: string): SocketDescriptor {
  const uid = effectiveUid();
  const stat = fs.lstatSync(file);
  if (!stat.isFile() || stat.isSymbolicLink() || (uid >= 0 && stat.uid !== uid) || (stat.mode & 0o077) !== 0 || stat.size > MAX_DESCRIPTOR_BYTES) {
    throw new SocketFilesError(`descriptor ${file} is not a private regular file owned by this user`);
  }
  const value = JSON.parse(fs.readFileSync(file, "utf8"));
  if (value?.format !== "nexus-socket/1" || typeof value.socket !== "string" || typeof value.token !== "string" || !TOKEN_PATTERN.test(value.token)) {
    throw new SocketFilesError(`descriptor ${file} is not a nexus-socket/1 descriptor`);
  }
  return value as SocketDescriptor;
}

